//! GitHub Actions publisher generated by `pixi-sandbox init`.

use super::{BOT_EMAIL, BOT_NAME, GENERATED_MARKER};
use crate::release::PIXI_SANDBOX_REPO;

/// Inputs whose values vary independently of the reviewed workflow template.
#[derive(Debug, Clone, Copy)]
pub struct GithubWorkflowOptions<'a> {
    /// Exact pixi-sandbox package and standalone-bootstrap version.
    pub version: &'a str,
    /// Sandbox plan path passed to `pixi-sandbox plan` in the consumer repository.
    pub config_path: &'a str,
    /// This file's own path, relative to the repository root — the upgrade job (AC#6) needs it
    /// to reproduce the exact `init` invocation that wrote it.
    pub workflow_path: &'a str,
    /// Relock workflow path, relative to the repository root, same reason as `workflow_path`.
    pub relock_workflow_path: &'a str,
    /// `relock.yml`'s own `--relock-ci-workflow` value, threaded through so the upgrade job's
    /// `init` call reproduces it exactly rather than falling back to a default that may differ.
    pub relock_ci_workflow: &'a str,
    /// Launcher path, relative to the repository root, same reason as `workflow_path`.
    pub script_path: &'a str,
    /// Branch `init` was run with — the launcher derives its default from this when the config
    /// cannot decide, so the upgrade job's `init --check` needs the same value to compare
    /// against the exact bytes `init` would have written.
    pub branch: &'a str,
    /// Resolved `on.push.paths:` allowlist (task-53 AC#2/#3) — already derived or overridden by
    /// the caller. Empty renders no `paths:` filter at all, matching the pre-task-53 template
    /// exactly (task-53 AC#1).
    pub push_paths: &'a [String],
    /// Scope `permissions:` to least privilege when `true` — `contents: read` top-level,
    /// `contents: write` only on the `publish` job (task-53 AC#2). `false` keeps today's
    /// unconditional top-level `contents: write`.
    pub scoped_permissions: bool,
    /// `(group, cancel_in_progress)` for a workflow-level `concurrency:` block, when configured.
    pub concurrency: Option<(&'a str, bool)>,
    /// `timeout-minutes:` for the `plan` job, when configured.
    pub plan_timeout_minutes: Option<u32>,
    /// `timeout-minutes:` for the `publish` job, when configured.
    pub publish_timeout_minutes: Option<u32>,
    /// Pin for `setup-pixi`'s own `pixi-version:` input, when configured.
    pub pixi_version: Option<&'a str>,
    /// `setup-pixi`'s `cache:` input, when configured. `None` renders no `cache:` key at all —
    /// the action's own default — matching the pre-task-53 template exactly.
    pub setup_pixi_cache: Option<bool>,
}

fn shell_word(value: &str) -> String {
    if !value.is_empty()
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"_./-".contains(&byte))
    {
        value.to_string()
    } else {
        format!("'{}'", value.replace('\'', "'\"'\"'"))
    }
}

/// Quote a scalar as a double-quoted YAML string. Always quotes, even where YAML would accept
/// a plain scalar — simple and unambiguous beats minimal for values that come from config, not
/// from a reviewed template (push-path entries, pin versions, a concurrency group name).
fn yaml_string(value: &str) -> String {
    format!("{value:?}")
}

/// Render the connected-side publisher workflow.
///
/// The connected CLI comes from the native prefix.dev package. A separately checksum-verified
/// standalone release binary is embedded as the transport bootstrap: package binaries are allowed
/// to use system linkage, while an airlock bootstrap must satisfy the stricter linkage policy.
#[must_use]
pub fn render_github_workflow(options: GithubWorkflowOptions<'_>) -> String {
    let template = r####"# __GENERATED_MARKER__
# __VERSION_STAMP__
name: publish sandbox

on:
  push:
    branches: [main]
__PUSH_PATHS_BLOCK__
  # A bare `schedule:` run and a `workflow_dispatch` naming `upgrade` both route to the
  # `upgrade` job below instead of an ordinary publish — see that job's `if:` and its
  # neighbours'. Leaving `upgrade` blank on a manual dispatch keeps today's behaviour exactly.
  schedule:
    - cron: "17 4 * * 1"
  workflow_dispatch:
    inputs:
      upgrade:
        description: >-
          Exact pixi-sandbox version to propose in an upgrade pull request (for example
          1.2.3). Leave blank for an ordinary manual publish run.
        required: false
        default: ""

permissions:
  __TOP_PERMISSIONS__
__CONCURRENCY_BLOCK__env:
  PIXI_SANDBOX_VERSION: __VERSION__
  PIXI_SANDBOX_CHANNEL: https://prefix.dev/archont561/archont561

jobs:
  plan:
    # The weekly schedule and an `upgrade`-naming dispatch both belong to the `upgrade` job
    # instead; an ordinary dispatch (the input left blank) still runs the normal publish.
    if: github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.upgrade == '')
    runs-on: ubuntu-latest
__PLAN_TIMEOUT_BLOCK__    outputs:
      matrix: ${{ steps.plan.outputs.matrix }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: prefix-dev/setup-pixi@d3f436a425481402e6a95a1d1fc10331c708cd9e # v0.10.2
        with:
          run-install: false
__SETUP_PIXI_EXTRA__      - name: Install pixi-sandbox CLI
        shell: bash
        run: >-
          pixi global install
          --channel "$PIXI_SANDBOX_CHANNEL"
          --channel conda-forge
          "pixi-sandbox==${PIXI_SANDBOX_VERSION}"
      - id: plan
        shell: bash
        run: echo "matrix=$(pixi-sandbox plan --config __CONFIG_PATH__ --json)" >> "$GITHUB_OUTPUT"

  publish:
    needs: plan
__PUBLISH_PERMISSIONS_BLOCK__    strategy:
      fail-fast: false
      # `include:` nested under `matrix:`, not `matrix:` itself. `plan --json` emits
      # {"schema":1,"include":[...]}, and Actions requires strategy.matrix to be an object.
      matrix:
        include: ${{ fromJSON(needs.plan.outputs.matrix).include }}
    runs-on: ${{ matrix.runner }}
__PUBLISH_TIMEOUT_BLOCK__    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
      - uses: prefix-dev/setup-pixi@d3f436a425481402e6a95a1d1fc10331c708cd9e # v0.10.2
        with:
          run-install: false
__SETUP_PIXI_EXTRA__      - name: Install pixi-sandbox CLI
        shell: bash
        run: >-
          pixi global install
          --channel "$PIXI_SANDBOX_CHANNEL"
          --channel conda-forge
          "pixi-sandbox==${PIXI_SANDBOX_VERSION}"

      # Consumer workflows embed the released, checksum-verified standalone binary. Building
      # from the checkout would incorrectly assume the consumer has pixi-sandbox's source tree
      # and its `package` environment; the checked-out tree belongs to the consumer project.
      - name: Download released pixi-sandbox
        id: bootstrap-unix
        if: runner.os != 'Windows'
        shell: bash
        run: |
          case "${{ matrix.platform }}" in
            linux-64) asset=pixi-sandbox-x86_64-unknown-linux-musl ;;
            linux-aarch64) asset=pixi-sandbox-aarch64-unknown-linux-musl ;;
            osx-64) asset=pixi-sandbox-x86_64-apple-darwin ;;
            osx-arm64) asset=pixi-sandbox-aarch64-apple-darwin ;;
            *) echo "::error::unsupported release platform: ${{ matrix.platform }}"; exit 2 ;;
          esac
          base="$GITHUB_SERVER_URL/__RELEASE_REPO__/releases/download/v${PIXI_SANDBOX_VERSION}"
          path="$RUNNER_TEMP/$asset"
          curl --fail --location --silent --show-error "$base/$asset" --output "$path"
          curl --fail --location --silent --show-error "$base/SHA256SUMS" --output "$RUNNER_TEMP/SHA256SUMS"
          grep "  $asset$" "$RUNNER_TEMP/SHA256SUMS" | sed "s#  $asset\$#  $path#" | sha256sum --check --status - || { echo "::error::SHA256 verification failed for $asset"; exit 1; }
          chmod +x "$path"
          echo "path=$path" >> "$GITHUB_OUTPUT"

      - name: Download released pixi-sandbox
        id: bootstrap-windows
        if: runner.os == 'Windows'
        shell: pwsh
        run: |
          $asset = switch ('${{ matrix.platform }}') {
            'win-64' { 'pixi-sandbox-x86_64-pc-windows-msvc.exe' }
            default { throw "unsupported release platform: ${{ matrix.platform }}" }
          }
          $base = "$env:GITHUB_SERVER_URL/__RELEASE_REPO__/releases/download/v$env:PIXI_SANDBOX_VERSION"
          $path = Join-Path $env:RUNNER_TEMP $asset
          Invoke-WebRequest -UseBasicParsing "$base/$asset" -OutFile $path
          Invoke-WebRequest -UseBasicParsing "$base/SHA256SUMS" -OutFile (Join-Path $env:RUNNER_TEMP 'SHA256SUMS')
          $expected = (Get-Content (Join-Path $env:RUNNER_TEMP 'SHA256SUMS') | Where-Object { $_ -match "  $([regex]::Escape($asset))$" }).Split()[0]
          if ((Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $expected.ToLowerInvariant()) { throw "SHA256 mismatch for $asset" }
          "path=$path" | Out-File -FilePath $env:GITHUB_OUTPUT -Append -Encoding utf8

      - name: Pack, verify, and publish
        if: runner.os != 'Windows'
        shell: bash
        env:
          ENVIRONMENTS: ${{ matrix.environments }}
          PLATFORM: ${{ matrix.platform }}
          BRANCH: ${{ matrix.branch }}
          CARGO_VENDOR: ${{ matrix.cargo_vendor }}
          SELF_BIN: ${{ steps.bootstrap-unix.outputs.path }}
          REMOTE: ${{ github.server_url }}/${{ github.repository }}.git
          PUSH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          LOG_DIR="$RUNNER_TEMP/pixi-sandbox-logs"
          LOG_FILE="$LOG_DIR/pipeline.log"
          rm -rf "$LOG_DIR"
          mkdir -p "$LOG_DIR"
          fail_phase() {
            local phase="$1"
            local exit_code="$2"
            echo "::error::publish pipeline failed during $phase (exit $exit_code)"
            if [ -n "${GITHUB_STEP_SUMMARY:-}" ]; then
              {
                echo "### ❌ pixi-sandbox publish failed on ${{ matrix.platform }}"
                echo ""
                echo "- **Failed phase**: \`$phase\` (exit code $exit_code)"
                echo "- **Branch**: \`${{ matrix.branch }}\`"
                echo "- **Diagnostic log**: uploaded as workflow artifact \`publish-diagnostics-${{ matrix.platform }}\`"
                echo ""
                if [ -s "$LOG_FILE" ]; then
                  echo "<details><summary>Diagnostic log excerpt (last 50 lines)</summary>"
                  echo ""
                  echo '```text'
                  tail -n 50 "$LOG_FILE"
                  echo '```'
                  echo "</details>"
                fi
              } >> "$GITHUB_STEP_SUMMARY" || true
            fi
            exit "$exit_code"
          }
          record() {
            local phase="$1"; shift
            echo "command=pipeline phase=$phase event=start" >> "$LOG_FILE"
            if ! "$@" 2>&1 | tee -a "$LOG_FILE"; then
              local status=${PIPESTATUS[0]}
              echo "command=pipeline phase=$phase result=failure exit=$status" >> "$LOG_FILE"
              fail_phase "$phase" "$status"
            fi
            echo "command=pipeline phase=$phase result=success" >> "$LOG_FILE"
          }
          IFS=',' read -ra ENVS <<< "$ENVIRONMENTS"
          for ENVIRONMENT in "${ENVS[@]}"; do
            record install pixi install --frozen -e "${ENVIRONMENT//[[:space:]]/}"
          done
          TRANSPORT="$RUNNER_TEMP/pixi-sandbox-transport"
          rm -rf "$TRANSPORT"
          CARGO_VENDOR_ARG=
          if [ "$CARGO_VENDOR" = true ]; then CARGO_VENDOR_ARG=--cargo-vendor; fi
          record pack "$SELF_BIN" pack \
            --repo-root . \
            --envs "$ENVIRONMENTS" \
            --output-dir "$TRANSPORT" \
            --platform "$PLATFORM" \
            --fetch-tools \
            --self-bin "$SELF_BIN" \
            --log-file "$LOG_DIR/pack.log" \
            $CARGO_VENDOR_ARG
          record doctor "$SELF_BIN" doctor --branch-location "$TRANSPORT" --verify --budget-config __CONFIG_PATH__ --log-file "$LOG_DIR/doctor.log"
          BASIC_AUTH=$(printf 'x-access-token:%s' "$PUSH_TOKEN" | base64 | tr -d '\r\n')
          export GIT_CONFIG_COUNT=1
          export GIT_CONFIG_KEY_0=http.extraheader
          export GIT_CONFIG_VALUE_0="AUTHORIZATION: basic $BASIC_AUTH"
          record publish "$SELF_BIN" publish --input-dir "$TRANSPORT" --branch-name "$BRANCH" --remote "$REMOTE" --log-file "$LOG_DIR/publish.log"

      - name: Pack, verify, and publish
        if: runner.os == 'Windows'
        shell: pwsh
        env:
          ENVIRONMENTS: ${{ matrix.environments }}
          PLATFORM: ${{ matrix.platform }}
          BRANCH: ${{ matrix.branch }}
          CARGO_VENDOR: ${{ matrix.cargo_vendor }}
          SELF_BIN: ${{ steps.bootstrap-windows.outputs.path }}
          REMOTE: ${{ github.server_url }}/${{ github.repository }}.git
          PUSH_TOKEN: ${{ github.token }}
        run: |
          $ErrorActionPreference = 'Stop'
          $PSNativeCommandUseErrorActionPreference = $true
          $logDir = Join-Path $env:RUNNER_TEMP 'pixi-sandbox-logs'
          $logFile = Join-Path $logDir 'pipeline.log'
          Remove-Item -Recurse -Force $logDir -ErrorAction SilentlyContinue
          New-Item -ItemType Directory -Path $logDir -Force | Out-Null
          function Fail-Phase($phase, $ex) {
            Write-Error "publish pipeline failed during $phase"
            if ($env:GITHUB_STEP_SUMMARY) {
              $summary = "### ❌ pixi-sandbox publish failed on ${{ matrix.platform }}`n`n- **Failed phase**: ``$phase```n- **Branch**: ``${{ matrix.branch }}```n- **Diagnostic log**: uploaded as workflow artifact ``publish-diagnostics-${{ matrix.platform }}```n"
              if (Test-Path $logFile) {
                $lines = Get-Content $logFile -Tail 50
                $summary += "`n<details><summary>Diagnostic log excerpt (last 50 lines)</summary>`n`n``````text`n" + ($lines -join "`n") + "`n```````n</details>`n"
              }
              $summary | Out-File -FilePath $env:GITHUB_STEP_SUMMARY -Append -Encoding utf8
            }
            throw $ex
          }
          function Invoke-Phase($phase, [scriptblock]$action) {
            "command=pipeline phase=$phase event=start" | Out-File -FilePath $logFile -Append -Encoding utf8
            try {
              & $action 2>&1 | Tee-Object -FilePath $logFile -Append
              if ($LASTEXITCODE -ne $null -and $LASTEXITCODE -ne 0) {
                throw "Command exited with status $LASTEXITCODE"
              }
              "command=pipeline phase=$phase result=success" | Out-File -FilePath $logFile -Append -Encoding utf8
            } catch {
              "command=pipeline phase=$phase result=failure error=$($_)" | Out-File -FilePath $logFile -Append -Encoding utf8
              Fail-Phase $phase $_
            }
          }
          foreach ($environment in ($env:ENVIRONMENTS -split ',')) {
            $envName = $environment.Trim()
            Invoke-Phase "install" { pixi install --frozen -e $envName }
          }
          $transport = Join-Path $env:RUNNER_TEMP 'pixi-sandbox-transport'
          Remove-Item -Recurse -Force $transport -ErrorAction SilentlyContinue
          $packLog = Join-Path $logDir 'pack.log'
          $packArgs = @('pack', '--repo-root', '.', '--envs', $env:ENVIRONMENTS, '--output-dir', $transport, '--platform', $env:PLATFORM, '--fetch-tools', '--self-bin', $env:SELF_BIN, '--log-file', $packLog)
          if ($env:CARGO_VENDOR -eq 'true') { $packArgs += '--cargo-vendor' }
          Invoke-Phase "pack" { & $env:SELF_BIN @packArgs }
          $doctorLog = Join-Path $logDir 'doctor.log'
          Invoke-Phase "doctor" { & $env:SELF_BIN doctor --branch-location $transport --verify --budget-config __CONFIG_PATH__ --log-file $doctorLog }
          $bytes = [System.Text.Encoding]::UTF8.GetBytes("x-access-token:$env:PUSH_TOKEN")
          $basic = [System.Convert]::ToBase64String($bytes)
          $env:GIT_CONFIG_COUNT = '1'
          $env:GIT_CONFIG_KEY_0 = 'http.extraheader'
          $env:GIT_CONFIG_VALUE_0 = "AUTHORIZATION: basic $basic"
          $publishLog = Join-Path $logDir 'publish.log'
          Invoke-Phase "publish" { & $env:SELF_BIN publish --input-dir $transport --branch-name $env:BRANCH --remote $env:REMOTE --log-file $publishLog }

      - name: Upload publish diagnostic log
        if: always()
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: publish-diagnostics-${{ matrix.platform }}
          path: ${{ runner.temp }}/pixi-sandbox-logs
          if-no-files-found: ignore
          retention-days: 7

  upgrade:
    name: upgrade
    if: github.event_name == 'schedule' || (github.event_name == 'workflow_dispatch' && inputs.upgrade != '')
    runs-on: ubuntu-latest
    # A job-level `permissions:` block replaces, not adds to, the workflow-level one above
    # (the same trap `relock.yml` documents): `pull-requests: write` has to be named here
    # explicitly, alongside `contents: write`, or the `gh pr create` step below gets a 403.
    permissions:
      contents: write
      pull-requests: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          # Workflow files require the optional Workflows-capable token. The built-in token is
          # still useful for checkout and the artifact-only fallback, but cannot deliver this PR.
          token: ${{ secrets.PIXI_SANDBOX_UPGRADE_TOKEN || github.token }}
          persist-credentials: true

      # Never trust a package manager's "latest" for anything that ends up in a committed
      # file (decision-4 / D16): bootstrap the version already pinned above — checksum
      # verified, exactly like the publish job's own bootstrap — then ask that exact binary to
      # self-update in place. Only the verified result of that self-update, never a floating
      # resolver, ever touches a generated file.
      - name: Download currently pinned pixi-sandbox
        id: bootstrap
        shell: bash
        run: |
          set -euo pipefail
          asset=pixi-sandbox-x86_64-unknown-linux-musl
          base="$GITHUB_SERVER_URL/__RELEASE_REPO__/releases/download/v${PIXI_SANDBOX_VERSION}"
          bin="$RUNNER_TEMP/pixi-sandbox"
          curl --fail --location --silent --show-error "$base/$asset" --output "$bin"
          curl --fail --location --silent --show-error "$base/SHA256SUMS" --output "$RUNNER_TEMP/SHA256SUMS"
          grep "  $asset$" "$RUNNER_TEMP/SHA256SUMS" | sed "s#  $asset\$#  $bin#" | sha256sum --check --status -
          chmod +x "$bin"
          echo "bin=$bin" >> "$GITHUB_OUTPUT"

      - name: Self-update to the requested version
        id: self-update
        shell: bash
        env:
          BIN: ${{ steps.bootstrap.outputs.bin }}
          UPGRADE_VERSION: ${{ inputs.upgrade }}
        run: |
          set -euo pipefail
          if [ -n "$UPGRADE_VERSION" ]; then
            "$BIN" self-update --dest "$BIN" --version "$UPGRADE_VERSION"
          else
            "$BIN" self-update --dest "$BIN"
          fi
          echo "version=$("$BIN" --version | awk '{print $NF}')" >> "$GITHUB_OUTPUT"

      - name: Check the owned files against the updated binary
        id: check
        shell: bash
        env:
          BIN: ${{ steps.bootstrap.outputs.bin }}
        run: |
          if "$BIN" init --check \
            --github-workflow-path __WORKFLOW_PATH__ \
            --relock-workflow-path __RELOCK_PATH__ \
            --relock-ci-workflow __RELOCK_CI_WORKFLOW__ \
            --script-path __SCRIPT_PATH__ \
            --config __CONFIG_PATH__ \
            --branch __BRANCH__; then
            echo "drift=false" >> "$GITHUB_OUTPUT"
          else
            echo "drift=true" >> "$GITHUB_OUTPUT"
          fi

      - name: Regenerate the owned files
        if: steps.check.outputs.drift == 'true'
        shell: bash
        env:
          BIN: ${{ steps.bootstrap.outputs.bin }}
        run: |
          set -euo pipefail
          "$BIN" init \
            --github-workflow-path __WORKFLOW_PATH__ \
            --relock-workflow-path __RELOCK_PATH__ \
            --relock-ci-workflow __RELOCK_CI_WORKFLOW__ \
            --script-path __SCRIPT_PATH__ \
            --config __CONFIG_PATH__ \
            --branch __BRANCH__

      # Config is reviewed data, never rewritten by `init` or this job (D16): only the three
      # owned paths are ever staged here, and a config the updated binary no longer understands
      # was already reported above, in prose, as a finding for a human to act on. A workflow-capable
      # token is optional: without it this job leaves a patch artifact and a precise hand-off,
      # rather than turning every consumer's weekly schedule red.
      - name: Prepare the upgrade patch
        id: delivery
        if: steps.check.outputs.drift == 'true'
        shell: bash
        env:
          GH_TOKEN: ${{ secrets.PIXI_SANDBOX_UPGRADE_TOKEN || github.token }}
          UPGRADE_TOKEN: ${{ secrets.PIXI_SANDBOX_UPGRADE_TOKEN }}
          VERSION: ${{ steps.self-update.outputs.version }}
        run: |
          set -uo pipefail
          artifact_dir="$RUNNER_TEMP/pixi-sandbox-upgrade"
          mkdir -p "$artifact_dir"
          git config user.name "__BOT_NAME__"
          git config user.email "__BOT_EMAIL__"
          branch="pixi-sandbox-upgrade/$VERSION"
          git checkout -B "$branch"
          git add __WORKFLOW_PATH__ __RELOCK_PATH__ __SCRIPT_PATH__
          if git diff --cached --quiet; then
            echo "::notice::init reported drift but left no staged changes; nothing to propose"
            exit 0
          fi
          git commit -m "chore(pixi-sandbox): upgrade generated files to $VERSION"
          git diff HEAD^ HEAD --binary > "$artifact_dir/pixi-sandbox-upgrade-$VERSION.patch"
          cp --parents __WORKFLOW_PATH__ __RELOCK_PATH__ __SCRIPT_PATH__ "$artifact_dir" 2>/dev/null || true

          write_handoff() {
            local reason="$1"
            {
              echo "### pixi-sandbox upgrade needs delivery credentials"
              echo
              echo "The generated files for version \"$VERSION\" are ready, but the upgrade PR was not opened."
              echo "Reason: $reason"
              echo
              echo "Configure the consumer secret \"PIXI_SANDBOX_UPGRADE_TOKEN\" with Workflows: write (PAT or GitHub App), then rerun this upgrade."
              echo "The patch is attached as the \"pixi-sandbox-upgrade-artifacts\" artifact and can be applied with git apply."
            } >> "${GITHUB_STEP_SUMMARY:-/dev/null}"
            echo "::error::upgrade PR delivery unavailable: $reason; configure PIXI_SANDBOX_UPGRADE_TOKEN with Workflows: write or apply the uploaded patch artifact"
          }

          if [ -z "$UPGRADE_TOKEN" ]; then
            write_handoff "PIXI_SANDBOX_UPGRADE_TOKEN is not configured"
            echo "delivery_refused=1" >> "$GITHUB_OUTPUT"
            exit 0
          fi

          if ! git push --force origin "$branch"; then
            write_handoff "the configured token was refused while pushing workflow files; it needs Workflows: write"
            echo "delivery_refused=1" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if ! gh pr create \
            --title "chore(pixi-sandbox): upgrade generated files to $VERSION" \
            --body "Regenerated by the scheduled pixi-sandbox upgrade job. A \`github.token\` merge starts no \`on: push\` workflow, so after merging run: gh workflow run __WORKFLOW_PATH__ --ref main" \
            --base main \
            --head "$branch"; then
            write_handoff "the branch was pushed but gh could not open the pull request"
            echo "delivery_refused=1" >> "$GITHUB_OUTPUT"
          fi

      - name: Upload upgrade patch and delivery report
        if: always() && steps.check.outputs.drift == 'true'
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: pixi-sandbox-upgrade-artifacts
          path: ${{ runner.temp }}/pixi-sandbox-upgrade
          if-no-files-found: ignore
          retention-days: 14
"####;

    // Every block below defaults to the exact string that disappears the placeholder line
    // entirely, so an unconfigured `GithubWorkflowOptions` renders byte-identical to the
    // pre-task-53 template (task-53 AC#1) — that property is the migration path for every
    // existing consumer, and is held directly by a golden-file test.
    let push_paths_block = if options.push_paths.is_empty() {
        String::new()
    } else {
        let mut block = String::from("    paths:\n");
        for path in options.push_paths {
            block.push_str(&format!("      - {}\n", yaml_string(path)));
        }
        block
    };

    let top_permissions = if options.scoped_permissions {
        "contents: read"
    } else {
        "contents: write"
    };

    let publish_permissions_block = if options.scoped_permissions {
        "    permissions:\n      contents: write\n".to_string()
    } else {
        String::new()
    };

    let concurrency_block = match options.concurrency {
        Some((group, cancel_in_progress)) => format!(
            "\nconcurrency:\n  group: {}\n  cancel-in-progress: {}\n\n",
            yaml_string(group),
            cancel_in_progress
        ),
        None => "\n".to_string(),
    };

    let plan_timeout_block = match options.plan_timeout_minutes {
        Some(minutes) => format!("    timeout-minutes: {minutes}\n"),
        None => String::new(),
    };
    let publish_timeout_block = match options.publish_timeout_minutes {
        Some(minutes) => format!("    timeout-minutes: {minutes}\n"),
        None => String::new(),
    };

    let setup_pixi_extra = {
        let mut block = String::new();
        if let Some(version) = options.pixi_version {
            block.push_str(&format!(
                "          pixi-version: {}\n",
                yaml_string(version)
            ));
        }
        if let Some(cache) = options.setup_pixi_cache {
            block.push_str(&format!("          cache: {cache}\n"));
        }
        block
    };

    template
        .replace("__GENERATED_MARKER__", GENERATED_MARKER)
        .replace(
            "__VERSION_STAMP__",
            &super::version_stamp_line(options.version),
        )
        .replace("__VERSION__", options.version)
        .replace("__CONFIG_PATH__", &shell_word(options.config_path))
        .replace("__RELEASE_REPO__", PIXI_SANDBOX_REPO)
        .replace("__WORKFLOW_PATH__", &shell_word(options.workflow_path))
        .replace("__RELOCK_PATH__", &shell_word(options.relock_workflow_path))
        .replace(
            "__RELOCK_CI_WORKFLOW__",
            &shell_word(options.relock_ci_workflow),
        )
        .replace("__SCRIPT_PATH__", &shell_word(options.script_path))
        .replace("__BRANCH__", &shell_word(options.branch))
        .replace("__BOT_NAME__", BOT_NAME)
        .replace("__BOT_EMAIL__", BOT_EMAIL)
        .replace("__PUSH_PATHS_BLOCK__\n", &push_paths_block)
        .replace("__TOP_PERMISSIONS__", top_permissions)
        .replace("__CONCURRENCY_BLOCK__", &concurrency_block)
        .replace("__PLAN_TIMEOUT_BLOCK__", &plan_timeout_block)
        .replace("__PUBLISH_PERMISSIONS_BLOCK__", &publish_permissions_block)
        .replace("__PUBLISH_TIMEOUT_BLOCK__", &publish_timeout_block)
        .replace("__SETUP_PIXI_EXTRA__", &setup_pixi_extra)
}
